Write and run screenshot script — cd multicode/duckpit/build/balance/check; cat > shot_v6g.js <<'EOF'
// Кадры страницы баланса v6g: ноутбук 1400×900 и телефон 390×844. usage: node shot_v6g.js <index.html> <outdir> [id,id,...]
const {chromium}=require('multicode/.cache/pw/node_modules/playwright-core');
const page=process.argv[2], out=process.argv[3], ids=(process.argv[4]||'kpi,chapters,key,rv,income,orders,afk,model').split(',');
(async()=>{
const b=await chromium.launch({executablePath:'/usr/bin/google-chrome',args:['--no-sandbox']});
const errs=[];const res={};
for(const [nm,vp] of [['desk',{width:1400,height:900}],['phone',{width:390,height:844}]]){
  const p=await b.newPage({viewport:vp,deviceScaleFactor:nm==='phone'?2:1});
  p.on('pageerror',e=>errs.push(nm+': '+e));p.on('console',m=>{if(m.type()==='error')errs.push(nm+': '+m.text())});
  await p.goto('file://'+page);await p.waitForTimeout(800);
  await p.screenshot({path:out+'/'+nm+'_top.png'});
  for(const id of ids){const el=await p.$('#'+id);if(!el){errs.push('no #'+id);continue}await el.screenshot({path:out+'/'+nm+'_'+id+'.png'});}
  res[nm]=await p.evaluate(()=>({h:document.body.scrollHeight,w:document.documentElement.scrollWidth,vw:innerWidth}));
  await p.close();
}
console.log(JSON.stringify({errs,res}));await b.close();})();
EOF
